// Match domains and registrars by array index. Use registrable domains, not URLs.
const domains = ['YOUR_DOMAIN_1', 'YOUR_DOMAIN_2'];
const registrars = ['Porkbun', 'babal.host'];
const warningDays = 60;
if (!Array.isArray(domains) || !Array.isArray(registrars) || domains.length !== registrars.length) {
  throw new Error('domains and registrars must be arrays with the same number of entries.');
}
const seen = new Set();
return domains.map((value, index) => {
  const domain = typeof value === 'string' ? value.trim().toLowerCase() : '';
  const registrar = typeof registrars[index] === 'string' ? registrars[index].trim() : '';
  if (domain.length > 253 || !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/i.test(domain)) {
    throw new Error(`Replace domain at index ${index} with a valid registrable domain (use punycode for IDNs).`);
  }
  if (!registrar) throw new Error(`Set the registrar at index ${index}.`);
  if (seen.has(domain)) throw new Error(`Duplicate domain: ${domain}`);
  seen.add(domain);
  return { json: { domain, registrar, warningDays } };
});

const reminders = [];
const now = Date.now();
for (const [index, item] of $input.all().entries()) {
  // Follow n8n item links so each response keeps its own domain and registrar.
  const { domain, registrar, warningDays } = $('Configure Domains').itemMatching(index).json;
  const response = item.json;
  if (response.error || response.statusCode !== 200) {
    console.warn(`Domain expiry lookup failed for ${domain}; check HTTP execution details.`);
    continue;
  }
  const events = Array.isArray(response.body?.events) ? response.body.events : [];
  const dates = events
    .filter(event => event && ['expiration', 'registrar expiration'].includes(event.eventAction))
    .map(event => Date.parse(event.eventDate))
    .filter(Number.isFinite);
  if (!dates.length) {
    console.warn(`No usable RDAP expiration date for ${domain}; verify with the registrar.`);
    continue;
  }
  const expiry = Math.min(...dates);
  const daysRemaining = Math.ceil((expiry - now) / 86400000);
  if (daysRemaining >= warningDays) continue;
  reminders.push({ domain, registrar, daysRemaining, expirationDate: new Date(expiry).toISOString() });
}
if (!reminders.length) return [];
reminders.sort((a, b) => a.daysRemaining - b.daysRemaining);
// Escape user-supplied labels for Slack; prevent mentions and injected links.
const escape = value => String(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/[\r\n]/g, ' ');
const lines = reminders.map(({ domain, registrar, daysRemaining, expirationDate }) =>
  `• ${escape(domain)} | ${escape(registrar)} | ${daysRemaining} days left | expires ${expirationDate.slice(0, 10)} (UTC)`);
return [{ json: { domains: reminders, message: `⚠️ DOMAIN EXPIRY REMINDER\n\n${lines.join('\n')}` } }];
